#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    // Input must be a valid positive integer with no extra characters
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 1) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 30) { // array size limit in the original binary
        puts("OUT_OF_RANGE");
        return 0;
    }
    unsigned long long cat[31];
    cat[0] = 1ULL;
    for (int i = 1; i < n; ++i) {
        unsigned long long sum = 0ULL;
        for (int j = 0; j < i; ++j) {
            sum += cat[j] * cat[i - 1 - j];
        }
        cat[i] = sum;
    }
    printf("%llu\n", cat[n - 1]);
    return 0;
}
